tool.command:
mkdir -p run && cd run &&
cp '$fix_file' model.fix &&
tar xzf '$instance_archive' &&
INST_D=\$(ls model-*.d   2>/dev/null | head -1) &&
INST_DAT=\$(ls model-*.dat 2>/dev/null | head -1) &&
if [ -z "\$INST_D" ] || [ -z "\$INST_DAT" ]; then
    echo "rfemsolve_thermal: could not find instance files in archive" > '$output_res';
    tar czf '$output_ensi' --files-from /dev/null;
    exit 1;
fi;
INST_BASE=\${INST_D%.d} &&
INST_ID=\${INST_BASE#model-} &&
mpirun -np \${GALAXY_SLOTS:-1} rfemsolve_thermal model "\$INST_ID" 2>&1;
RC=\$?;
RES="\${INST_BASE}.res";
if [ -f "\$RES" ]; then cp "\$RES" '$output_res'; else echo "Solver produced no .res (exit \${RC})" > '$output_res'; fi;
if ls "\${INST_BASE}.ensi."* 1>/dev/null 2>&1; then
    tar czf '$output_ensi' "\${INST_BASE}.ensi."*;
else
    tar czf '$output_ensi' --files-from /dev/null;
fi;
exit \${RC}
